    val serviceRunning: StateFlow<Boolean> = _serviceRunning

    fun publish(s: Snapshot) {
        _snapshot.value = s
        _findings.value = Diagnoser.analyze(s)
    }

    fun setServiceRunning(running: Boolean) {
        _serviceRunning.value = running
    }
}

